=# The user provided the following image and text.

## IMAGE CONTENT:
{{ $json.content }}

## USER MESSAGE:
{{ 
  (function(){
    const body = $('WAHA Trigger').item.json.payload.body || "";
    const trimmed = body.trim();

    if (trimmed === "/i") {
      return "Describe the image";
    }
    if (trimmed.startsWith("/i ")) {
      return trimmed.replace("/i ", "");
    }
    return trimmed;
  })()
}}
